using System;
using UnityEngine;
using UnityEngine.UI;
namespace SokobanStudio {
[DisallowMultipleComponent] public class GameBootstrap:MonoBehaviour {
 public string levelId="level_01";public GameState State{get;private set;}LevelData level;BoardView board;Canvas canvas;Text moves,pushes;GameObject modal;bool victory,completionPulse;int number;
 void Start(){canvas=StudioUI.Canvas(transform);if(!string.IsNullOrEmpty(Navigation.Selected)){levelId=Navigation.Selected;Navigation.Selected=null;}try{level=LevelJson.Load(Resources.Load<TextAsset>("PresetLevels").text,levelId);State=new GameState(level);int.TryParse(levelId.Replace("level_",""),out number);var header=StudioUI.Panel(canvas.transform,"HUD",new Vector2(0,.86f),Vector2.one,StudioUI.PanelColor);var title=StudioUI.Rect(header,"Title",new Vector2(0,.52f),new Vector2(.5f,1),Vector2.zero);StudioUI.Text(title,number>=1&&number<=PresetProgress.LevelCount?Navigation.Names[number-1]:levelId,22);moves=StudioUI.Text(StudioUI.Rect(header,"Moves",new Vector2(.5f,.52f),new Vector2(.75f,1),Vector2.zero),"");pushes=StudioUI.Text(StudioUI.Rect(header,"Pushes",new Vector2(.75f,.52f),new Vector2(1,1),Vector2.zero),"");var actions=StudioUI.Rect(header,"Actions",new Vector2(.18f,.06f),new Vector2(.82f,.48f),Vector2.zero);var layout=actions.gameObject.AddComponent<HorizontalLayoutGroup>();layout.spacing=10;layout.childForceExpandWidth=true;layout.childControlWidth=true;layout.childControlHeight=true;StudioUI.Button(actions,"Pause",Pause);StudioUI.Button(actions,"Undo",Undo);StudioUI.Button(actions,"Restart",Restart);StudioUI.Button(actions,"Level Select",()=>Navigation.Menu(true));var viewport=StudioUI.Rect(canvas.transform,"Map Viewport",new Vector2(.02f,.05f),new Vector2(.98f,.84f),Vector2.zero);var hint=StudioUI.Rect(canvas.transform,"Hints",Vector2.zero,new Vector2(1,.045f),Vector2.zero);StudioUI.Text(hint,"MOVE  WASD / Arrows     |     UNDO  Z     |     RESTART  R     |     PAUSE  Esc",17);board=new GameObject("Board View").AddComponent<BoardView>();board.transform.SetParent(transform);board.Initialize(new Rect(0,0,1,.78f));board.Viewport=viewport;Refresh();}catch(Exception e){StudioUI.Text(canvas.transform,"Unable to load level: "+e.Message);enabled=false;}}
 void Close(){StudioUI.Remove(modal);modal=null;}
 public void Undo(){Close();if(State.Undo())FeedbackAudio.Play("undo");victory=false;completionPulse=false;Refresh();}
 public void Restart(){Close();FeedbackAudio.Play("restart");State.Restart();victory=false;completionPulse=false;Refresh();}
 public void Pause(){if(modal||State.Won)return;board.Show(level,State);var card=StudioUI.Modal(canvas.transform,"PAUSED");modal=card.parent.gameObject;StudioUI.Button(card,"Resume",Close);StudioUI.Button(card,"Restart",Restart);StudioUI.Button(card,"Level Select",()=>Navigation.Menu(true));}
 void Refresh(){board.Show(level,State);UpdateCounts();}
 void UpdateCounts(){moves.text="Moves: "+State.Moves;pushes.text="Pushes: "+State.Pushes;}
 void Win(){victory=true;FeedbackAudio.Play("complete");Navigation.Progress.Complete(number);var card=StudioUI.Modal(canvas.transform,number==PresetProgress.LevelCount?"ALL LEVELS COMPLETE!":"MISSION COMPLETE!");modal=card.parent.gameObject;StudioUI.RowText(card,number>=1&&number<=PresetProgress.LevelCount?Navigation.Names[number-1]:level.name,20,36);StudioUI.RowText(card,"Moves: "+State.Moves+"    Pushes: "+State.Pushes,22,45);if(number<PresetProgress.LevelCount)StudioUI.Button(card,"Next Level",()=>Navigation.Play(number+1));StudioUI.Button(card,"Retry",Restart);StudioUI.Button(card,"Level Select",()=>Navigation.Menu(true));if(Navigation.Progress.Error!=null)StudioUI.RowText(card,Navigation.Progress.Error,16,60);}
 void Update(){if(State==null||PlayInput.Typing)return;if(modal){if(victory&&Input.GetKeyDown(KeyCode.Z))Undo();else if(!victory&&Input.GetKeyDown(KeyCode.Escape))Close();return;}if(Input.GetKeyDown(KeyCode.Escape)){Pause();return;}if(Input.GetKeyDown(KeyCode.Z)){Undo();return;}if(Input.GetKeyDown(KeyCode.R)){Restart();return;}if(State.Won){if(!victory&&!board.Busy){if(!completionPulse){completionPulse=true;board.Celebrate();}else Win();}return;}if(board.Busy)return;Cell? direction=PlayInput.Direction();if(direction.HasValue){if(State.Move(direction.Value)){board.Animate(level,State);UpdateCounts();}else board.Blocked(direction.Value);}}
}
}
